#include <assert.h>
#include <stdint.h>
#include <string.h>
#include "amtari.h"
struct vdi_fixture{uint16_t opcode;int calls;}; struct line_fixture{int calls;int16_t x1,y1,x2,y2;uint16_t color,style;}; struct aes_fixture{uint16_t opcode;int calls;};
static int32_t vd(void*o,uint16_t op,const int16_t*i,uint16_t ni,const int16_t*p,uint16_t np,int16_t*out,uint16_t oc,uint16_t*no,int16_t*po,uint16_t pc,uint16_t*npo){struct vdi_fixture*f=o;(void)i;(void)ni;(void)p;(void)np;(void)oc;(void)pc;f->opcode=op;++f->calls;out[0]=42;po[0]=320;po[1]=200;*no=1;*npo=2;return 0;}
static int line(void*o,int16_t x1,int16_t y1,int16_t x2,int16_t y2,uint16_t color,uint16_t style){struct line_fixture*f=o;++f->calls;f->x1=x1;f->y1=y1;f->x2=x2;f->y2=y2;f->color=color;f->style=style;return 0;}
static int32_t aes(void*o,uint16_t op,const int16_t*i,uint16_t ni,int16_t*out,uint16_t oc,uint16_t*no,const uint32_t*ai,uint16_t nai,uint32_t*ao,uint16_t oac,uint16_t*nao){struct aes_fixture*f=o;(void)i;(void)ni;(void)ai;(void)nai;(void)ao;(void)oac;(void)nao;assert(oc>=1u);f->opcode=op;++f->calls;out[0]=77;*no=1u;return 0;}
static void w16(uint8_t*m,uint32_t a,uint16_t v){m[a]=(uint8_t)(v>>8);m[a+1]=(uint8_t)v;}
static void w32(uint8_t*m,uint32_t a,uint32_t v){w16(m,a,(uint16_t)(v>>16));w16(m,a+2,(uint16_t)v);}
static void setup_pb(uint8_t*m,uint16_t opcode){w32(m,0x100,0x140);w32(m,0x104,0x180);w32(m,0x108,0x1c0);w32(m,0x10c,0x200);w32(m,0x110,0x280);w16(m,0x140,opcode);w16(m,0x142,0);w16(m,0x146,0);}
static void setup_aespb(uint8_t*m,uint16_t opcode,uint16_t ni,uint16_t no,uint16_t nai,uint16_t nao){w32(m,0x300,0x340);w32(m,0x304,0x360);w32(m,0x308,0x380);w32(m,0x30c,0x3c0);w32(m,0x310,0x400);w32(m,0x314,0x440);w16(m,0x340,opcode);w16(m,0x342,ni);w16(m,0x344,no);w16(m,0x346,nai);w16(m,0x348,nao);}
int main(void){struct amtari_context c={0};struct vdi_fixture v={0};struct line_fixture l={0};struct aes_fixture a={0};int16_t out[64]={0},po[16]={0},p[6]={10,20,30,40,50,60},in[2]={7,9};uint32_t ai[1]={UINT32_C(0x12345678)},ao[2]={0};uint16_t no=0,npo=0,x;uint8_t mem[2048];assert(amtari_init(&c)==0);assert(strcmp(amtari_version(),AMTARI_VERSION)==0);assert(amtari_vdi_configure(&c,640,400,16)==0);
assert(amtari_vdi_dispatch(&c,1,0,0,0,0,out,64,&no,po,16,&npo)==0);assert(no==45&&npo==12);assert(out[0]==639&&out[1]==399&&out[13]==16);assert(po[0]==0&&po[11]==0);
assert(amtari_vdi_line_bind(&c,line,&l)==0);in[0]=3;assert(amtari_vdi_dispatch(&c,15,in,1,0,0,out,64,&no,po,16,&npo)==0);assert(no==1&&out[0]==3);in[0]=5;assert(amtari_vdi_dispatch(&c,17,in,1,0,0,out,64,&no,po,16,&npo)==0);assert(no==1&&out[0]==5);assert(amtari_vdi_dispatch(&c,6,0,0,p,6,out,64,&no,po,16,&npo)==0);assert(l.calls==2);assert(amtari_vdi_bind(&c,vd,&v)==0);assert(amtari_vdi_dispatch(&c,100,0,0,0,0,out,64,&no,po,16,&npo)==0);assert(v.calls==1&&v.opcode==100);
assert(amtari_aes_set_application_name(&c,"AMTARI")==0);no=99u;npo=99u;assert(amtari_aes_dispatch(&c,10,0,0,out,64,&no,0,0,ao,2,&npo)==0);assert(out[0]==1&&c.aes.application_active);assert(amtari_aes_dispatch(&c,19,0,0,out,64,&no,0,0,ao,2,&npo)==0);assert(!c.aes.application_active);assert(amtari_aes_bind(&c,aes,&a)==0);assert(amtari_aes_dispatch(&c,99,in,2,out,64,&no,ai,1,ao,2,&npo)==0);assert(a.calls==1&&out[0]==77);
memset(mem,0,sizeof(mem));assert(amtari_guest_memory_bind(&c,mem,sizeof(mem))==0);w16(mem,0x20,0x4e42);setup_pb(mem,100);c.cpu.pc=0x20;c.cpu.d[0]=0x0073;c.cpu.d[1]=0x100;assert(amtari_exec_step(&c)==AMTARI_EXEC_RUNNING);assert(c.cpu.pc==0x22);assert(v.calls==2);assert(amtari_guest_read16(&c,0x200,&x)==0&&x==42);
memset(mem,0,sizeof(mem));w16(mem,0x20,0x4e42);setup_pb(mem,1);c.cpu.pc=0x20;c.cpu.d[0]=0x0073;c.cpu.d[1]=0x100;assert(amtari_exec_step(&c)==AMTARI_EXEC_RUNNING);assert(amtari_guest_read16(&c,0x14c,&x)==0&&x==2);assert(amtari_guest_read16(&c,0x148,&x)==0&&x==45);
/* M3.13: init, find by AES name, then exit through real TRAP #2 calls. */
memset(mem,0,sizeof(mem));w16(mem,0x20,0x4e42);setup_aespb(mem,10,0,1,0,0);c.cpu.pc=0x20;c.cpu.d[0]=0x00c8;c.cpu.d[1]=0x300;assert(amtari_exec_step(&c)==AMTARI_EXEC_RUNNING);assert(amtari_guest_read16(&c,0x3c0,&x)==0&&x==2);
memcpy(mem+0x480,"AMTARI",7);setup_aespb(mem,13,0,1,1,0);w32(mem,0x400,0x480);w16(mem,0x20,0x4e42);c.cpu.pc=0x20;c.cpu.d[0]=0x00c8;c.cpu.d[1]=0x300;assert(amtari_exec_step(&c)==AMTARI_EXEC_RUNNING);assert(amtari_guest_read16(&c,0x3c0,&x)==0&&x==2);
memcpy(mem+0x480,"OTHER",6);w16(mem,0x20,0x4e42);c.cpu.pc=0x20;assert(amtari_exec_step(&c)==AMTARI_EXEC_RUNNING);assert(amtari_guest_read16(&c,0x3c0,&x)==0&&x==0xffffu);
setup_aespb(mem,19,0,1,0,0);w16(mem,0x20,0x4e42);c.cpu.pc=0x20;assert(amtari_exec_step(&c)==AMTARI_EXEC_RUNNING);assert(!c.aes.application_active);return 0;}
